using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<WeatherForecast> forecastInfo = webOptions.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"GetTypeInfo<WeatherForecast> => Type: {forecastInfo.Type.Name}, Props: {forecastInfo.Properties.Count}");

// Serialize via the typed metadata
var forecast = new WeatherForecast("Sunny", 27);
string json = JsonSerializer.Serialize(forecast, forecastInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// 2a. Type the resolver knows about (default reflection resolver handles any public type)
if (webOptions.TryGetTypeInfo<WeatherForecast>(out JsonTypeInfo<WeatherForecast>? found))
    Console.WriteLine($"TryGet WeatherForecast => found ({found!.Type.Name})");
else
    Console.WriteLine("TryGet WeatherForecast => not found");

// 2b. Restricted options with a source-gen context that only knows about WeatherForecast
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = DemoContext.Default
};

if (restricted.TryGetTypeInfo<WeatherForecast>(out var hit))
    Console.WriteLine($"TryGet WeatherForecast (restricted) => found ({hit!.Type.Name})");
else
    Console.WriteLine("TryGet WeatherForecast (restricted) => not found");

// int is NOT in DemoContext, so this should return false — no exception
if (restricted.TryGetTypeInfo<int>(out var miss))
    Console.WriteLine($"TryGet int (restricted) => found ({miss!.Type.Name})");
else
    Console.WriteLine("TryGet int (restricted) => not found (as expected)");

